(function () {
  var slides = Array.prototype.slice.call(document.querySelectorAll('.slide'));
  var progress = document.querySelector('.progress');
  var counter = document.getElementById('counter');
  var index = 0;

  function fromHash() {
    var n = parseInt((location.hash || '').replace('#', ''), 10);
    return isNaN(n) ? 0 : Math.min(Math.max(n - 1, 0), slides.length - 1);
  }

  function show(i) {
    index = Math.min(Math.max(i, 0), slides.length - 1);
    slides.forEach(function (s, k) { s.classList.toggle('active', k === index); });
    if (progress) progress.style.width = ((index + 1) / slides.length * 100) + '%';
    if (counter) counter.textContent = (index + 1) + ' / ' + slides.length;
    if (('#' + (index + 1)) !== location.hash) {
      history.replaceState(null, '', '#' + (index + 1));
    }
  }

  function next() { show(index + 1); }
  function prev() { show(index - 1); }

  document.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') { next(); e.preventDefault(); }
    else if (e.key === 'ArrowLeft' || e.key === 'PageUp') { prev(); e.preventDefault(); }
    else if (e.key === 'Home') { show(0); }
    else if (e.key === 'End') { show(slides.length - 1); }
    else if (e.key === 't' || e.key === 'T') { toggleTheme(); }
  });

  function toggleTheme() {
    var root = document.documentElement;
    root.setAttribute('data-theme', root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark');
  }

  window.addEventListener('hashchange', function () { show(fromHash()); });

  var nextBtn = document.getElementById('next');
  var prevBtn = document.getElementById('prev');
  var themeBtn = document.getElementById('theme');
  if (nextBtn) nextBtn.addEventListener('click', next);
  if (prevBtn) prevBtn.addEventListener('click', prev);
  if (themeBtn) themeBtn.addEventListener('click', toggleTheme);

  show(fromHash());
})();
